-- INSERT IGNORE, not ON DUPLICATE KEY: MariaDB on production does not take
-- the row-alias form, and a slug that somehow already exists should be left
-- alone rather than overwritten by a scrape.
INSERT IGNORE INTO doctor
    (full_name, slug, specialty_code, qualifications, years_experience, bio,
     photo_url, languages, verification, source, accepts_bookings, active, created_at, updated_at)
VALUES
    ('Dos. Dr. Həyat Əliyeva', 'dos-dr-heyat-eliyeva', NULL, '1986-1992-ci illər Azərbaycan Tibb Universiteti müalicə profilaktika fakültəsi. | | 1992-1993-cü illər İnternatura ATU Dəmiryol xəstəxanası.', 34, 'Konfranslar: 2011-ci il Türkiyə İstanbul Yıldız Texnik Universitetinin kimya və gen mühəndisliyi şöbəsi (Western-blot, İFA, İFM, ZPR).; ; 2013-cü il ATU-nin "innovasiya" şöbəsi (Tədrisin təkmilləşməsi).; ; 2015-ci il Türkiyə İstanbul Yıldız Texnik Universitetinin kimya və gen mühəndisliyi şöbəsi (Mikrokultivasiya üsulu).; ; VI-INTERNATIONAL EUROPEAN CONFERENCE ON INTERDISCIPLINARY SCIENTIFIC RESEARCH held on August 26-27, 2022 / Bucharest, Romania.; ; Əməkdar elm xadimi, Tibb elmləri doktoru, Professor H.A. Sultanovun 90 illik yubileyinə həsr olunmuş "Koloproktologiyanın aktual problemləri"Beynəlxalq elmi-praktik konfransında iştirak etmiş və 5 DTT balı qazanmışdır.; ; 2-4 May 2024-cü il tarixlərində Baku Fairmont Hotel Flame Towers-də keçirilən "2-ci Beynəlxalq Azərbaycan Laborator Tibb Konqresi & Lab Expo"-nun sədri.; ; Antimikrob rezistentliyin diaqnostikasında və müalicəsində müasir yanaşmalar adı seminar.; ; 20 Noyabr 2023-cü il Ümumdünya Səhiyyə Təşkilatının Azərbaycandakı Ölkə Ofisinin həyata keçirdiyi Cərrahi bölgə infeksiyalarının profilaktikası adlı 90 dəqiqəlik vebinarda iştirak etmişdir..', '/doctor-photos/dos-dr-heyat-eliyeva.webp', 'az', 'UNCLAIMED', 'referansclc.com', 0, 1, NOW(), NOW()),
    ('Dr. Abid Həlimov', 'dr-abid-helimov', 'internal-medicine', '1972-1978-ci illər Azərbaycan Tibb Univesiteti, Müalicə Profilaktika fakültəsi', 48, 'Fəaliyyət sahələri: Ürək-damar və qan sistemi xəstəlikləri; hipertoniya, ürəyin işemik xəstəlikləri, ürək çatışmazlığı; ; Tənəffüs sistemi xəstəlikləri: bronxial astma, kəskin və xroniki broxit, kəskin respirator xəstəliklər və s.; ; Həzm sistemi xəstəlikləri: mədə və onikibarmaq bağırsaq xorası; ; Kəskin və xroniki qastroduodenit; ; İltihabi mədə-bağısaq sistemi xəstəlikləri.; ; Hepatit, Pankreatit; ; Sidik-cinsiyyət sistemi xəstəlikləri; ; Revmatik xəstəliklər və s..', '/doctor-photos/dr-abid-helimov.webp', 'az', 'UNCLAIMED', 'referansclc.com', 0, 1, NOW(), NOW()),
    ('Dr. Adil Baloğlanov', 'dr-adil-baloglanov', 'internal-medicine', '1979-1985-ci illərdə Azərbaycan Tibb Universiteti, Terapiya fakültəsi | | 1985-1986-ci illərdə Bakı Şəhəri Təcili və Təxirəsalınmaz Tibbi Yardım Stansiyasındada, İnternatura', 41, 'Fəaliyyət sahələri: Yaş və risk qruplarına uyğun check up müayinələrin təşkili; ; Qida borusu və mədə-bağırsaq sistemi xəstəliklərinin müayinə və müalicəsi; ; QERX (Qastroezofageal reflüks xəstəliyi); ; Barrett sindromu - Qida borusu selikli qişasında reflüksə bağlı dəyişikliklər; ; Kəskin və xroniki qastrit - Helikobakter Pilori infeksiyası ilə əlaqəli və ya digər səbəblərə bağlı mədə iltihabı; ; Mədə və 12 barmaq bağırsaq xorası; ; Funksional dispepsiya; ; Divertikulyar xəstəlik (divertikulit); ; Qeyri-spesifik xoralı kolit və Kron xəstəliyi - İltihabi bağırsaq xəstəliklərinin diaqnostikası və müalicəsi; ; Bağırsaq disbakteriozu - Mikrobiom tarazlığının pozulması, şişkinlik və diskomfort; ; Psevdomembranoz kolit - Antibiotik istifadəsindən sonra yaranan ciddi bağırsaq infeksiyası; ; Qıcıqlanmış bağırsaq sindromu (qəbizlik, diareya ilə) - Stress, qidalanma və digər səbəblərlə əlaqəli bağırsaq hərəkətləri pozuntusu; ; Virus hepatitləri (A, B, C, D) - Yoluxma yollarına və forma görə fərqli yanaşma tələb edən infeksiyalar; ; Qeyri-alkoqollu steatohepatit (qaraciyər piylənməsi) - Metabolik sindrom və artıq çəki fonunda yaranan qaraciyər pozuntusu; ; Alkoqollu qaraciyər xəstəliyi - Uzunmüddətli spirtli içki istifadəsinin təsiri ilə yaranan dəyişikliklər; ; Autoimmun hepatit; ; Birincili biliar sirroz; ; Qaraciyər sirrozu - Qaraciyərin funksional toxumasının çapıq toxuması ilə əvəz olunması, qaraciyər çatışmazlığı riski; ; Lyambliyoz, askaridoz, enterobioz, toksokaroz və s. - Uşaqlarda və böyüklərdə tez-tez rast gəlinən helmint və protozoon infeksiyalar; ; COVID-19 sonrası və digər virus xəstəliklərindən sonra reabilitasiya - Ağciyər, ürək və sinir sistemində yaranmış qalıq təsirlərin dəyərləndirilməsi və bərpası; ; Hipertoniya, taxikardiya, aritmiya və digər dövran pozğunluqları; ; Bronxit, astma, pnevmoniya və digər ağciyər xəstəlikləri; ; Sidik yollarının infeksiyaları, sistit, pielonefrit və s. müayinə və müalicəsi. Konfranslar: 1987-ci ildə Təcili yardım üzrə ümumi təkminlləşdirmə kursu; ; 1990-cı ildə Ə.Əliyev adına A.D.H.T. İnstitutunda "Kiliniki Kardioqrafiya" kursu; ; 1995-ci ildə Ə. Əliyev adına A.D.H.T. İnstitutunda "İntensiv Terapiya" kursu; ; 1999 Ə.Əliyev adına A.D.H.T. İnstitutunda "Urologiya" kursu.', '/doctor-photos/dr-adil-baloglanov.webp', 'az', 'UNCLAIMED', 'referansclc.com', 0, 1, NOW(), NOW()),
    ('Dr. Afət Kərimova', 'dr-afet-kerimova', 'obstetrics-gynecology', NULL, NULL, 'Fəaliyyət sahələri: Sonsuz cütlüklərin dəstəklənməsi və sonsuzluğun müalicəsi; ; Uşaqlıqdaxili inseminasiya (aşılama); ; Menstrual disfunksiyanın müalicəsi; ; Uşaqlıq boynu patologiyalarının ("eroziyanın") profilaktikası (peyvənd), erkən diaqnostikası (pap-smear + HPV skrininq, servikal biopsiya) və müalicəsi (elektro- və lazerkoagulyasiya); ; Cinsi yolla ötürülən infeksiyaların diaqnostikası və müalicəsi; ; Kolposkopiya; ; Ailə planlaması (spiralin taxılması, oral kontraseptivlərin təyini, dərialtı implantın yerləşdirilməsi, sterilizasiya); ; Ginekoloji xəstəliklərin USM diaqnostikası; ; Uroginikologiya (sidik saxlama problemlərinin müayinəsi və müalicəsi); ; HSQ (boruların yoxlanılması).', '/doctor-photos/dr-afet-kerimova.webp', 'az', 'UNCLAIMED', 'referansclc.com', 0, 1, NOW(), NOW()),
