INSERT INTO doctor_clinic (doctor_id, clinic_id)
SELECT d.id, c.id
FROM referans_placement p
JOIN doctor d ON d.slug = p.doctor_slug AND d.source = 'referansclc.com'
JOIN clinic c ON c.slug = p.clinic_slug
WHERE NOT EXISTS (
    SELECT 1 FROM doctor_clinic dc
    WHERE dc.doctor_id = d.id AND dc.clinic_id = c.id);

DROP TEMPORARY TABLE referans_placement;
